sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var id = g_user.userID;
    var user = g_form.getValue('assigned_to');
    if (id == user || oldValue == '') {
        var outcome = g_form.getValue('outcome');
        var trade_task_type = g_form.getValue('trade_task_type');
        var decision = g_form.getValue('decision');
        var decisionReason = g_form.getValue('decision_reason');
        if ((outcome == 'Leave the Sanctioned Trade Pending' || outcome == 'Progress the Sanctioned Trade') && trade_task_type == 'Maker') {
            g_form.setMandatory('work_notes', true);
        } else if (decision == 'Reject and create a new task' && decisionReason == 'Other') {
            g_form.setMandatory('work_notes', true);
        } else {
            g_form.setMandatory('work_notes', false);
        }
    } else {
        g_form.setMandatory('work_notes', true);
    }

}
